checks = {"1 + 2 * 3": 7.0, "(1 + 2) * 3": 9.0, "2 ^ 3 ^ 2": 512.0, "-2 ^ 2": -4.0, "2 ^ -1": 0.5, "7 % 3": 1.0, "-7 % 3": 2.0, '"a" + "b"': "ab", "not 1 == 2": True, "true == 1": False, "false and 1 / 0": False, "true or 1 / 0": True, 'if(1 < 2, "yes", 1 / 0)': "yes", 'len("hello")': 5.0, "min(3, 1, 2)": 1.0, 'str(3.0)': "3", 'num(" 4.5 ")': 4.5}
for source, expected in checks.items(): assert evaluate(source) == expected, source
